17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.LocalDate;
20	import java.util.function.Predicate;
21	
22	/**
23	 * Builds and parses an owner's {@code memberId}, the single unified identity formatted as
24	 * {@code "<REGION><FY><HASH8><CHK>"} where:
25	 * <ul>
26	 * <li>{@code REGION} is the owner's canonical region (for example {@code "NSW"}),</li>
27	 * <li>{@code FY} is the two-digit {@link FiscalYear fiscal year} of the registration date,</li>
28	 * <li>{@code HASH8} is the first eight upper-case hex characters of
29	 * {@code SHA-256(normalizedTelephone + lastName)} (the region-and-hash identity), and</li>
30	 * <li>{@code CHK} is a single {@link LuhnCheckDigit Luhn check digit} over the digits of
31	 * {@code <REGION><FY><HASH8>}.</li>
32	 * </ul>
33	 */
34	public final class MemberIdGenerator {
35	
36	    /** Separator introducing the numeric suffix appended when de-duplicating a member id. */
37	    private static final String SEPARATOR = "-";
38	
39	    /** Number of upper-case hex characters kept from the digest. */
40	    private static final int HASH_LENGTH = 8;
41	
42	    private MemberIdGenerator() {
43	    }
44	
45	    /**
46	     * Format a member id as {@code "<REGION><FY><HASH8><CHK>"} (for example
47	     * {@code "NSW261A2B3C4D7"}).
48	     *
49	     * @param region              the owner's canonical region
50	     * @param registrationDate    the owner's registration date, whose fiscal year supplies {@code FY}
51	     * @param normalizedTelephone the owner's normalized (E.164) telephone
52	     * @param lastName            the owner's last name
53	     * @return the formatted member id
54	     */
55	    public static String format(String region, LocalDate registrationDate, String normalizedTelephone,
56	            String lastName) {
57	        String base = region + FiscalYear.twoDigit(registrationDate) + hash8(normalizedTelephone, lastName);
58	        return base + LuhnCheckDigit.compute(base);
59	    }
60	
61	    /**
62	     * De-duplicate a formatted member id against the ids already in use. When {@code baseMemberId}
63	     * is free it is returned unchanged; otherwise {@code "-<n>"} is appended using the smallest
64	     * {@code n >= 2} that yields an id {@code isTaken} reports as free.
65	     *
66	     * @param baseMemberId the freshly formatted member id (see {@link #format})
67	     * @param isTaken      tests whether a candidate id already belongs to another owner
68	     * @return a member id that {@code isTaken} reports as free
69	     */
70	    public static String deduplicate(String baseMemberId, Predicate<String> isTaken) {
71	        if (!isTaken.test(baseMemberId)) {
72	            return baseMemberId;
73	        }
74	        for (int n = 2; ; n++) {
75	            String candidate = baseMemberId + SEPARATOR + n;
76	            if (!isTaken.test(candidate)) {
77	                return candidate;
78	            }
79	        }
80	    }
81	
82	    /**
83	     * Extract the {@code REGION} prefix from a member id produced by {@link #format}: its leading
84	     * run of letters, which precedes the numeric fiscal-year segment.
85	     *
86	     * @param memberId the member id, may be {@code null}
87	     * @return the region prefix, or {@code null} when the member id is {@code null}
88	     */
89	    public static String region(String memberId) {
90	        if (memberId == null) {
91	            return null;
92	        }
93	        int end = 0;
94	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
95	            end++;
96	        }
97	        return memberId.substring(0, end);
98	    }
99	
100	    private static String hash8(String normalizedTelephone, String lastName) {
101	        String key = orEmpty(normalizedTelephone) + orEmpty(lastName);
102	        return Sha256.hex(key).substring(0, HASH_LENGTH).toUpperCase();
103	    }
104	
105	    private static String orEmpty(String value) {
106	        return value == null ? "" : value;
107	    }
108	}
