17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Derives an owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}, by combining
21	 * their membership tier with the area implied by their locality.
22	 */
23	public final class OwnerSegment {
24	
25	    private OwnerSegment() {
26	    }
27	
28	    /**
29	     * Compose the owner's segment from their membership level and locality.
30	     *
31	     * @param membershipLevel the owner's membership level
32	     * @param locality the owner's canonical region (locality), may be {@code null}
33	     * @return the segment, one of {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'},
34	     * {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}
35	     */
36	    public static String of(int membershipLevel, String locality) {
37	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
38	        String area = LocalityResolver.isKnownRegion(locality) ? "METRO" : "REGIONAL";
39	        return tier + "_" + area;
40	    }
41	}
