17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	import java.util.Set;
21	
22	/**
23	 * Derives an owner's {@code locality} (canonical region), preferring the postcode range
24	 * (via {@link PostcodePolicy}) and falling back to a fixed city-to-region table when the
25	 * postcode is absent or in no known range.
26	 */
27	public final class LocalityResolver {
28	
29	    private static final String UNKNOWN = "UNKNOWN";
30	
31	    private static final Map<String, String> CITY_REGION = Map.of(
32	        "Sydney", "NSW",
33	        "Melbourne", "VIC",
34	        "Brisbane", "QLD");
35	
36	    private static final Set<String> KNOWN_REGIONS = Set.of("NSW", "VIC", "QLD");
37	
38	    private LocalityResolver() {
39	    }
40	
41	    /**
42	     * Resolve the canonical region for an owner, preferring the postcode.
43	     *
44	     * @param city the owner's city, may be {@code null}
45	     * @param postcode the owner's postcode, may be {@code null}
46	     * @return the region derived from the postcode range when it is known, otherwise the
47	     * region from the city table, or {@code "UNKNOWN"} when neither is known
48	     */
49	    public static String resolve(String city, String postcode) {
50	        return PostcodePolicy.regionForPostcode(postcode).orElseGet(() -> regionForCity(city));
51	    }
52	
53	    /**
54	     * Resolve an owner's locality from its {@code memberId}, whose {@code REGION} prefix is the
55	     * canonical region. Falls back to {@link #resolve(String, String)} for owners that predate the
56	     * member id (and so have none), keeping their locality unchanged.
57	     *
58	     * @param memberId the owner's member id, may be {@code null}
59	     * @param city the owner's city, used only for the fallback, may be {@code null}
60	     * @param postcode the owner's postcode, used only for the fallback, may be {@code null}
61	     * @return the region carried by the member id, or the city/postcode-derived region when the
62	     * member id is absent
63	     */
64	    public static String fromMemberId(String memberId, String city, String postcode) {
65	        String region = MemberIdGenerator.region(memberId);
66	        return region != null && !region.isEmpty() ? region : resolve(city, postcode);
67	    }
68	
69	    /**
70	     * Resolve the canonical region for the given city using the fixed city-to-region table.
71	     *
72	     * @param city the owner's city, may be {@code null}
73	     * @return the region string from the fixed table, or {@code "UNKNOWN"} when the
74	     * city is not in the table
75	     */
76	    public static String regionForCity(String city) {
77	        if (city == null) {
78	            return UNKNOWN;
79	        }
80	        return CITY_REGION.getOrDefault(city, UNKNOWN);
81	    }
82	
83	    /**
84	     * Report whether the given region is one of the known canonical regions (NSW, VIC or QLD),
85	     * as opposed to {@code "UNKNOWN"} or any unrecognised value.
86	     *
87	     * @param region the canonical region (locality), may be {@code null}
88	     * @return {@code true} when the region is a known region, {@code false} otherwise
89	     */
90	    public static boolean isKnownRegion(String region) {
91	        return KNOWN_REGIONS.contains(region);
92	    }
93	}
