265	    protected Set<Pet> getPetsInternal() {
266	        if (this.pets == null) {
267	            this.pets = new HashSet<>();
268	        }
269	        return this.pets;
270	    }
271	
272	    protected void setPetsInternal(Set<Pet> pets) {
273	        this.pets = pets;
274	    }
275	
276	    public List<Pet> getPets() {
277	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
278	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
279	        return Collections.unmodifiableList(sortedPets);
280	    }
281	
282	    public void setPets(List<Pet> pets) {
283	        this.pets = new HashSet<>(pets);
284	    }
285	
