18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Shared helper for SHA-256 hashing, returning the digest as a lower-case hex string. Callers
25	 * that need a fixed-width, upper-case identifier take a prefix and upper-case it themselves.
26	 */
27	public final class Sha256 {
28	
29	    private Sha256() {
30	    }
31	
32	    /**
33	     * Compute the SHA-256 digest of the UTF-8 bytes of {@code value} as a lower-case hex string.
34	     *
35	     * @param value the value to hash
36	     * @return the 64-character lower-case hex digest
37	     */
38	    public static String hex(String value) {
39	        try {
40	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(digest.length * 2);
42	            for (byte b : digest) {
43	                sb.append(String.format("%02x", b));
44	            }
45	            return sb.toString();
46	        } catch (NoSuchAlgorithmException e) {
47	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
48	        }
49	    }
50	}
