18	
19	import java.util.Locale;
20	
21	/**
22	 * Computes the standard (American) Soundex code of a name: an upper-case letter followed by three
23	 * digits that group names sharing a similar pronunciation. Non-letters are ignored, the first
24	 * letter is kept verbatim, and the remaining consonants are mapped to their Soundex digit;
25	 * adjacent letters mapping to the same digit (including when separated only by {@code h} or
26	 * {@code w}) collapse to a single digit, while letters separated by a vowel are coded separately.
27	 * The code is right-padded with zeros or truncated to exactly four characters.
28	 */
29	public final class Soundex {
30	
31	    /** Length of a Soundex code: the retained first letter plus three digits. */
32	    private static final int LENGTH = 4;
33	
34	    private Soundex() {
35	    }
36	
37	    /**
38	     * Compute the Soundex code of the given name.
39	     *
40	     * @param name the name to encode (may be {@code null})
41	     * @return the four-character Soundex code, or an empty string when {@code name} is {@code null}
42	     * or contains no letters
43	     */
44	    public static String encode(String name) {
45	        if (name == null) {
46	            return "";
47	        }
48	        String letters = lettersOnly(name);
49	        if (letters.isEmpty()) {
50	            return "";
51	        }
52	        StringBuilder code = new StringBuilder(LENGTH);
53	        code.append(letters.charAt(0));
54	        char previous = digit(letters.charAt(0));
55	        for (int i = 1; i < letters.length() && code.length() < LENGTH; i++) {
56	            char letter = letters.charAt(i);
57	            if (letter == 'H' || letter == 'W') {
58	                // h and w never contribute a digit and do not separate equal digits.
59	                continue;
60	            }
61	            char digit = digit(letter);
62	            if (digit != '0' && digit != previous) {
63	                code.append(digit);
64	            }
65	            previous = digit;
66	        }
67	        while (code.length() < LENGTH) {
68	            code.append('0');
69	        }
70	        return code.toString();
71	    }
72	
73	    private static String lettersOnly(String name) {
74	        StringBuilder sb = new StringBuilder(name.length());
75	        for (char c : name.toUpperCase(Locale.ROOT).toCharArray()) {
76	            if (c >= 'A' && c <= 'Z') {
77	                sb.append(c);
78	            }
79	        }
80	        return sb.toString();
81	    }
82	
83	    /**
84	     * Map an upper-case letter to its Soundex digit, returning {@code '0'} for the vowels and for
85	     * {@code y}, {@code h} and {@code w}, which are not coded.
86	     */
87	    private static char digit(char letter) {
88	        switch (letter) {
89	            case 'B': case 'F': case 'P': case 'V':
90	                return '1';
91	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
92	                return '2';
93	            case 'D': case 'T':
94	                return '3';
95	            case 'L':
96	                return '4';
97	            case 'M': case 'N':
98	                return '5';
99	            case 'R':
100	                return '6';
101	            default:
102	                return '0';
103	        }
104	    }
105	}
