17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.LocalDate;
20	import java.time.Month;
21	
22	/**
23	 * Utilities for the business fiscal year, which starts on 1 July. A fiscal year is identified by
24	 * the calendar year in which it begins: every date from 1 July of year {@code Y} up to 30 June of
25	 * year {@code Y + 1} belongs to fiscal year {@code Y}.
26	 */
27	public final class FiscalYear {
28	
29	    /** The month on whose first day each fiscal year begins. */
30	    private static final Month FISCAL_YEAR_START = Month.JULY;
31	
32	    private FiscalYear() {
33	    }
34	
35	    /**
36	     * Return the calendar year in which the fiscal year containing {@code date} began: the date's
37	     * own year from 1 July onwards, otherwise the previous calendar year.
38	     *
39	     * @param date the date whose fiscal year to resolve
40	     * @return the fiscal year's starting calendar year
41	     */
42	    public static int startingYear(LocalDate date) {
43	        int year = date.getYear();
44	        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? year : year - 1;
45	    }
46	
47	    /**
48	     * Return the last two digits of the fiscal year's starting calendar year, zero-padded (for
49	     * example {@code "26"} for fiscal year 2026).
50	     *
51	     * @param date the date whose fiscal year to format, may be {@code null}
52	     * @return the two-digit fiscal year, or {@code null} if {@code date} is {@code null}
53	     */
54	    public static String twoDigit(LocalDate date) {
55	        if (date == null) {
56	            return null;
57	        }
58	        return String.format("%02d", startingYear(date) % 100);
59	    }
60	
61	    /**
62	     * Format the fiscal year containing {@code date} as {@code "FY<YY>"}, where {@code YY} is the
63	     * last two digits of the fiscal year's starting calendar year, zero-padded (for example
64	     * {@code "FY26"}).
65	     *
66	     * @param date the date whose fiscal year to format, may be {@code null}
67	     * @return the formatted fiscal year, or {@code null} if {@code date} is {@code null}
68	     */
69	    public static String label(LocalDate date) {
70	        if (date == null) {
71	            return null;
72	        }
73	        return "FY" + twoDigit(date);
74	    }
75	
76	    /**
77	     * Return the number of whole fiscal years elapsed from {@code from} to {@code to}: the count of
78	     * 1 July boundaries crossed between the two dates. Never negative.
79	     *
80	     * @param from the earlier date
81	     * @param to   the later date
82	     * @return the number of elapsed fiscal years, never negative
83	     */
84	    public static int elapsed(LocalDate from, LocalDate to) {
85	        return Math.max(startingYear(to) - startingYear(from), 0);
86	    }
87	}
