17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Computes a single Luhn check digit over the digits contained in a string.
21	 */
22	public final class LuhnCheckDigit {
23	
24	    private LuhnCheckDigit() {
25	    }
26	
27	    /**
28	     * Compute the Luhn check digit (0-9) over the digits contained in {@code value}, ignoring any
29	     * non-digit characters. Doubling starts from the rightmost digit.
30	     *
31	     * @param value the value whose digits are checked, or {@code null}
32	     * @return the Luhn check digit, or {@code null} when {@code value} is {@code null}
33	     */
34	    public static Integer compute(String value) {
35	        if (value == null) {
36	            return null;
37	        }
38	        int sum = 0;
39	        boolean doubleDigit = true;
40	        for (int i = value.length() - 1; i >= 0; i--) {
41	            char c = value.charAt(i);
42	            if (c < '0' || c > '9') {
43	                continue;
44	            }
45	            int d = c - '0';
46	            if (doubleDigit) {
47	                d *= 2;
48	                if (d > 9) {
49	                    d -= 9;
50	                }
51	            }
52	            sum += d;
53	            doubleDigit = !doubleDigit;
54	        }
55	        return (10 - (sum % 10)) % 10;
56	    }
57	}
