252	    /**
253	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
254	     * already reached this many owners is rejected as a conflict.
255	     */
256	    static final int MAX_OWNERS_PER_CITY = 50;
257	
258	    /**
259	     * Number of owners that must already exist in a city before a new owner registered there is
260	     * flagged with a capacity warning. Once the count already recorded for the city reaches this
261	     * value (but is still below {@link #MAX_OWNERS_PER_CITY}), the new owner carries
262	     * {@code capacityWarning == true} to signal that the city is approaching its capacity limit.
263	     */
264	    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
265	
266	    /**
267	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
268	     * already reached this many registrations is rejected as a rate-limit violation.
269	     */
270	    static final int MAX_OWNERS_PER_DAY = 100;
271	
272	    /**
273	     * Number of owners that must already have registered on a day before a new registration is
274	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
275	     * value, the new owner carries {@code bulkSignupWarning == true}.
276	     */
277	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
278	
279	    @Override
280	    @Transactional
281	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
282	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
283	            throw new DisposableEmailDomainException(owner.getEmail());
284	        }
285	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
286	        rejectIdentityCollision(owner);
287	        List<Owner> householdMembers = findHouseholdMembers(owner);
288	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
289	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
290	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
291	        }
292	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
293	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
294	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
295	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
296	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
297	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
298	        }
299	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
300	        flagPossibleDuplicate(owner, sharesHousehold);
301	        owner.setNamesakeCount(countNamesakes(owner));
302	        owner.setHouseholdSize(householdMembers.size() + 1);
303	        owner.setMembershipLevel(OwnerMembership.cappedLevel(owner, householdMembers));
304	        owner.setMemberId(assignMemberId(owner));
305	        ownerRepository.save(owner);
306	        ownerAuditLogger.ownerCreated(owner);
307	        welcomeNotifier.welcome(owner);
308	        return owner.getHouseholdId();
309	    }
310	
311	    /**
312	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
313	     * another active owner. Because the telephone is part of the key, only an existing owner sharing
314	     * every key component (normalized telephone, lower-cased email and the last name's Soundex code)
315	     * is a hard duplicate; telephone equality remains a prerequisite, so it prefilters the candidates.
316	     */
317	    private void rejectIdentityCollision(Owner owner) {
318	        String identityKey = OwnerIdentityKey.of(owner);
319	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
320	            .filter(ClinicServiceImpl::isActive)
321	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
322	        if (collides) {
323	            throw new DuplicateOwnerException(identityKey);
324	        }
325	    }
326	
327	    /**
328	     * Whether an existing owner is still active, i.e. has not been soft-deleted. Soft-deleted owners
329	     * are retained for history but ignored by the create-time duplicate and identity checks.
330	     */
331	    private static boolean isActive(Owner owner) {
332	        return !Boolean.TRUE.equals(owner.getDeleted());
333	    }
334	
335	    /**
336	     * Build the new owner's {@code memberId} and de-duplicate it against existing owners. The base
337	     * id is derived from the owner's locality, registration date, telephone and last name; if it
338	     * already belongs to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2)
339	     * that is still free.
340	     */
341	    private String assignMemberId(Owner owner) {
342	        String baseId = MemberIdGenerator.format(
343	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
344	            owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName());
345	        Set<String> takenIds = ownerRepository.findByMemberIdStartingWith(baseId).stream()
346	            .map(Owner::getMemberId)
347	            .collect(Collectors.toSet());
348	        return MemberIdGenerator.deduplicate(baseId, takenIds::contains);
349	    }
350	
351	    /**
352	     * Flag the new owner as a possible (soft) duplicate of an existing owner whose identity key
353	     * <em>differs</em> but whose last name shares the same Soundex code and whose postcode is equal.
354	     * The new owner is still created; {@code possibleDuplicate} is set to whether such a match exists
355	     * and {@code possibleDuplicateOf} to the matching owner's id (the lowest when several match), or
356	     * {@code null} when there is no match.
357	     *
358	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
359	     * member rather than a suspected duplicate, so it is never flagged.
360	     */
361	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
362	        Owner match = sharesHousehold ? null : findSoftMatchCandidates(owner).stream()
363	            .min(Comparator.comparingInt(Owner::getId))
364	            .orElse(null);
365	        owner.setPossibleDuplicate(match != null);
366	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
367	    }
368	
369	    /**
370	     * Find the existing active owners that are a soft match for the new owner: those sharing its
371	     * postcode and its last name's {@link org.springframework.samples.petclinic.util.Soundex Soundex}
372	     * code, but deriving a <em>different</em> {@link OwnerIdentityKey identity key} (an equal key is a
373	     * hard duplicate, rejected earlier). An owner without a postcode has no soft-match candidates.
374	     */
375	    private List<Owner> findSoftMatchCandidates(Owner owner) {
376	        if (owner.getPostcode() == null) {
377	            return List.of();
378	        }
379	        String soundex = Soundex.encode(owner.getLastName());
380	        String identityKey = OwnerIdentityKey.of(owner);
381	        return ownerRepository.findByPostcode(owner.getPostcode()).stream()
382	            .filter(ClinicServiceImpl::isActive)
383	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
384	            .filter(existing -> !identityKey.equals(OwnerIdentityKey.of(existing)))
385	            .toList();
386	    }
387	
388	    @Override
389	    @Transactional
390	    public void saveOwner(Owner owner) throws DataAccessException {
391	        ownerRepository.save(owner);
392	    }
393	
394	    /**
395	     * Count the owners that already exist sharing this owner's first name and last name, compared
396	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
397	     */
398	    private int countNamesakes(Owner owner) {
399	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
400	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
401	            .count();
402	    }
403	
404	    /**
405	     * Find the existing owners that already share this owner's household, i.e. that derive the same
406	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
407	     * has no household peers.
408	     */
409	    private List<Owner> findHouseholdMembers(Owner owner) {
410	        if (owner.getPostcode() == null) {
411	            return List.of();
412	        }
413	        String householdId = owner.getHouseholdId();
414	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
415	            .filter(ClinicServiceImpl::isActive)
416	            .filter(existing -> householdId.equals(
417	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
418	            .toList();
419	    }
