30	/**
31	 * Emits audit records for owner lifecycle events to the dedicated {@code AUDIT} logger,
32	 * keeping audit-trail concerns out of the business logic that triggers them.
33	 */
34	@Component
35	public class OwnerAuditLogger {
36	
37	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
38	
39	    private static final ObjectMapper EVENT_MAPPER = JsonMapper.builder().build();
40	
41	    /** Source of the monotonically increasing sequence number carried by each event. */
42	    private final AtomicLong sequence = new AtomicLong();
43	
44	    /**
45	     * Record that an owner was successfully created. Emits both the human-readable
46	     * audit line and an immutable structured {@link OwnerCreatedEvent} as JSON, so
47	     * downstream consumers can process the event without parsing the free-form line.
48	     *
49	     * @param owner the persisted owner (with its generated id) to audit
50	     */
51	    public void ownerCreated(Owner owner) {
52	        AUDIT.info(
53	            "Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
54	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel(owner));
55	        OwnerCreatedEvent event = new OwnerCreatedEvent(
56	            sequence.incrementAndGet(), owner.getId(), primaryIdentifier(owner), membershipLevel(owner));
57	        AUDIT.info(EVENT_MAPPER.writeValueAsString(event));
58	    }
59	
60	    /**
61	     * The owner's current primary identifier: their unified {@code memberId}.
62	     */
63	    private static String primaryIdentifier(Owner owner) {
64	        return owner.getMemberId();
65	    }
66	
67	    private static int membershipLevel(Owner owner) {
68	        return OwnerMembership.level(owner);
69	    }
70	}
